import type { Account, LedgerEntry } from './domain.js';

export function fixtureAccount(overrides: Partial<Account>): Account {
  return { id: 'acc_1', ...overrides } as unknown as Account;
}

export function coerceEntry(row: Record<string, string>): LedgerEntry {
  const entry = row as unknown as LedgerEntry;
  return entry;
}
